Бэкенд проверяет **HMAC-SHA256 с токеном бота**, партнёр — **Ed25519 публичным ключом Telegram**. Передавайте исходную строку `Telegram.WebApp.initData`, а не `initDataUnsafe`. Это два официальных способа проверки: [HMAC](https://core.telegram.org/bots/webapps#validating-data-received-via-the-mini-app), [Ed25519](https://core.telegram.org/bots/webapps#validating-data-for-third-party-use).

Для Ed25519 нужен пакет `cryptography`: `pip install cryptography`.

```python
import base64
import binascii
import hashlib
import hmac
import json
import time
from urllib.parse import parse_qsl

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey


TELEGRAM_KEYS = {
    "prod": "e7bf03a2fa4602af4580703d88dda5bb59f32ed8b02a56c187fe7d34caed242d",
    "test": "40055058a4ee38156a06562e52eece92a771bcd8346a8c4615cb7376eddf72ec",
}


def _parse(raw: str) -> dict:
    # URL-декодирование ровно один раз; пустые значения сохраняем.
    pairs = parse_qsl(
        raw, keep_blank_values=True, strict_parsing=True,
        encoding="utf-8", errors="strict",
    )
    data = dict(pairs)
    if len(data) != len(pairs):
        raise ValueError("Повторяющиеся параметры initData")
    return data


def _check_string(data: dict, excluded: set) -> bytes:
    # JSON внутри значений до проверки не разбираем и не пересериализуем.
    return "\n".join(
        f"{key}={value}"
        for key, value in sorted(data.items())
        if key not in excluded
    ).encode("utf-8")


def _verified_user(data: dict, max_age: int) -> dict:
    # Вызывать только после успешной криптографической проверки.
    try:
        auth_date = int(data["auth_date"])
    except (KeyError, ValueError):
        raise ValueError("Некорректный auth_date") from None

    now = int(time.time())
    if not now - max_age <= auth_date <= now + 30:
        raise ValueError("initData просрочены или датированы будущим")

    try:
        user = json.loads(data["user"])
    except (KeyError, ValueError):
        raise ValueError("Отсутствует или некорректен user") from None

    if (
        not isinstance(user, dict)
        or type(user.get("id")) is not int
        or user["id"] <= 0
    ):
        raise ValueError("Некорректный user.id")
    return user


# 1. Ваш бэкенд: токен доступен только серверу.
def verify_with_token(
    raw: str, bot_token: str, *, max_age: int = 300
) -> dict:
    data = _parse(raw)
    try:
        received_hash = bytes.fromhex(data["hash"])
    except (KeyError, ValueError):
        raise ValueError("Отсутствует или некорректен hash") from None

    secret = hmac.new(
        b"WebAppData", bot_token.encode("utf-8"), hashlib.sha256
    ).digest()

    # Исключаем ТОЛЬКО hash; signature, если есть, включаем.
    expected_hash = hmac.new(
        secret, _check_string(data, {"hash"}), hashlib.sha256
    ).digest()

    if not hmac.compare_digest(expected_hash, received_hash):
        raise ValueError("Неверный hash")
    return _verified_user(data, max_age)


# 2. Сервис партнёра: токен бота не нужен.
def verify_for_partner(
    raw: str, bot_id: int, *, environment: str = "prod",
    max_age: int = 300,
) -> dict:
    data = _parse(raw)
    try:
        encoded = data["signature"]
        signature = base64.b64decode(
            encoded + "=" * (-len(encoded) % 4),
            altchars=b"-_",
            validate=True,
        )
    except (KeyError, ValueError, binascii.Error):
        raise ValueError("Отсутствует или некорректна signature") from None

    if len(signature) != 64:
        raise ValueError("Некорректная длина signature")

    public_key = Ed25519PublicKey.from_public_bytes(
        bytes.fromhex(TELEGRAM_KEYS[environment])
    )
    message = (
        f"{bot_id}:WebAppData\n".encode("utf-8")
        + _check_string(data, {"hash", "signature"})
    )

    try:
        public_key.verify(signature, message)
    except InvalidSignature:
        raise ValueError("Неверная signature") from None

    return _verified_user(data, max_age)
```

Применение на соответствующих серверах:

```python
# Ваш бэкенд:
user = verify_with_token(init_data, BOT_TOKEN)

# Партнёр:
user = verify_for_partner(init_data, bot_id=123456789)

telegram_user_id = user["id"]
```

`bot_id` и окружение партнёр берёт из доверенной конфигурации. После успеха используйте возвращённый `user["id"]` для идентификации; ошибки `ValueError` обрабатывайте как отказ в аутентификации.

Срок 300 секунд и допуск часов 30 секунд — выбранная политика приложения. Проверка срока ограничивает повторное использование данных; для одноразовых операций нужен отдельный учёт повторов.
